type fakeTransport struct{}
func (fakeTransport) RoundTrip(request *http.Request) (*http.Response, error) {
    if err := request.Context().Err(); err != nil { return nil, err }
    return &http.Response{
        StatusCode: http.StatusOK, Header: make(http.Header),
        Body: io.NopCloser(strings.NewReader("ready")), Request: request,
    }, nil
}
func main() {
    ctx, cancel := context.WithTimeout(context.Background(), time.Hour)
    defer cancel()
    request, err := http.NewRequestWithContext(ctx, http.MethodGet, "https://example.invalid/study", nil)
    if err != nil { panic(err) }
    client := &http.Client{Transport: fakeTransport{}}
    response, err := client.Do(request)
    if err != nil { fmt.Println("deadline:", errors.Is(err, context.DeadlineExceeded)); return }
    body, readErr := io.ReadAll(response.Body)
    closeErr := response.Body.Close()
    if readErr != nil || closeErr != nil { fmt.Println("body error"); return }
    fmt.Println(response.StatusCode, string(body))
}

